  "implementation": "def solve(case):
    nodes = case['payload']['nodes']
    required_symbols = set(case['payload']['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])
    present = set(node_map.keys())
    removal_order = []
    # sort by depth descending, then id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    # helper to get all present descendants (including node)
    def subtree_ids(nid):
        stack = [nid]
        res = set()
        while stack:
            curr = stack.pop()
            if curr in present:
                res.add(curr)
                for c in children.get(curr, []):
                    stack.append(c)
        return res
    for n in sorted_nodes:
        nid = n['id']
        if nid not in present:
            continue
        if n['parent'] is None:  # root
            continue
        if not n['removable']:
            continue
        if n['symbol'] in required_symbols:
            continue
        # check retained children
        has_retained_child = any(c in present for c in children.get(nid, []))
        if has_retained_child:
            continue
        # compute subtree to be removed
        sub = subtree_ids(nid)
        # check required symbols remain
        # For each required symbol, see if any node with that symbol outside the subtree is still present
        ok = True
        for sym in required_symbols:
            # find a node with this symbol not in sub and still present
            found = False
            for node in nodes:
                if node['id'] in present and node['id'] not in sub and node['symbol'] == sym:
                    found = True
                    break
            if not found:
                ok = False
                break
        if ok:
            # remove all nodes in sub
            for rid in sub:
                present.discard(rid)
            removal_order.append(nid)
    retained = sorted(present)
    return {'retained': retained, 'removal_order': removal_order}
